package ir.neshane.isolationprobe.recovery;

import static ir.neshane.isolationprobe.recovery.LabRecoveryTrust.*;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;

/** Independent synthetic current Authority; its database is never a restore target. */
public final class LabRecoveryAuthority {
    private final Path d;
    private final String incarnation;
    private final Set<String> nonces=ConcurrentHashMap.newKeySet();
    private volatile boolean available=true;
    private volatile String fault="";
    private final Map<String,Map<String,String>> historical=new HashMap<>();
    LabRecoveryAuthority(Path d)throws Exception{this.d=d;incarnation=Files.readString(d.resolve("authority-incarnation")).strip();}
    private Connection db()throws Exception{return database(d,"db","authority-db","dr_authority","verify-full","");}
    private Map<String,String> signed(Map<String,String> s)throws Exception{return map("code","OK","body",packed(s),"signature",sign(d,s));}
    private Map<String,String> state(String tenant)throws Exception{
        try(var c=db()){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);Map<String,String> result;
            try(var p=c.prepareStatement("SELECT cell_id,placement_epoch,credential_epoch,fence_generation,version,suspended FROM authority.current_state WHERE tenant_id=?")){p.setString(1,tenant);try(var r=p.executeQuery()){require(r.next(),"UNKNOWN_TENANT");result=map("tenant",tenant,"cell",r.getString(1),"deployment","lab-deployment","placement",""+r.getLong(2),"credential",""+r.getLong(3),"fence",""+r.getLong(4),"revision",""+r.getLong(5),"suspended",""+r.getBoolean(6),"authority-incarnation",incarnation);}}
            var ledger=new TreeMap<String,String>();try(var p=c.prepareStatement("SELECT sequence,payload FROM authority.completions WHERE tenant_id=? ORDER BY sequence")){p.setString(1,tenant);try(var r=p.executeQuery()){while(r.next())ledger.put(""+r.getLong(1),r.getString(2)==null?"":r.getString(2));}}result.put("ledger",packed(ledger));result.put("checkpoint",""+ledger.size());c.commit();return result;}
    }
    private synchronized Map<String,String> handle(String peer,Map<String,String> r)throws Exception{
        String cmd=r.get("command");boolean admin=r.containsKey("mac");if(admin){require(peer.equals("driver"),"ADMIN_PEER");admin(d,r,nonces);}
        if(admin)switch(cmd){
            case "health":return map("code","OK");
            case "availability":available=Boolean.parseBoolean(r.get("value"));return map("code","OK");
            case "fault":fault=r.get("value");return map("code","OK");
            case "remember":historical.put(r.get("tenant"),state(r.get("tenant")));return map("code","OK");
            case "advance":{
                String tenant=r.get("tenant"),field=r.get("field");require(Set.of("placement_epoch","credential_epoch","fence_generation","suspended").contains(field),"AUTHORITY_FIELD_ALLOWLIST");
                var drained=call(d,"restored-owner",8443,map("command","fence","tenant",tenant));require("OK".equals(drained.get("code")),"DESTINATION_FENCE_UNCONFIRMED");
                try(var c=db();var p=c.prepareStatement("UPDATE authority.current_state SET "+field+"="+(field.equals("suspended")?"NOT suspended":field+"+1")+",version=version+1 WHERE tenant_id=?")){p.setString(1,tenant);require(p.executeUpdate()==1,"UNKNOWN_TENANT");}return signed(state(tenant));}
            case "backup-manifest":{var m=unpack(r.get("body"));var current=state(m.get("tenant"));require(m.get("cell").equals(current.get("cell"))&&m.get("deployment").equals("lab-deployment"),"BACKUP_SCOPE");for(String f:List.of("placement","credential","fence","checkpoint"))require(m.get(f).equals(current.get(f)),"BACKUP_SNAPSHOT_BINDING");return signed(m);}
            case "grant":{var g=unpack(r.get("body"));if(!r.getOrDefault("negative-fixture","false").equals("true")){var current=state(g.get("tenant"));for(String f:List.of("tenant","cell","deployment","placement","credential","fence","revision"))require(current.get(f).equals(g.get(f)),"RECOVERY_GRANT_SCOPE");long i=Long.parseLong(g.get("issued")),e=Long.parseLong(g.get("expires"));require(e>i&&e-i<=120000&&g.get("executor").equals("recovery-executor")&&g.get("destination").equals("restored-owner"),"RECOVERY_GRANT_BOUNDARY");}String signature=sign(d,g);try(var c=db();var p=c.prepareStatement("INSERT INTO authority.recovery_grants(grant_id,body,signature,state) VALUES (?,?,?,'ISSUED')")){p.setString(1,g.get("grant"));p.setString(2,packed(g));p.setString(3,signature);p.executeUpdate();}return map("code","OK","body",packed(g),"signature",signature);}
            case "fixture-ledger":{
                String tenant=r.get("tenant"),mode=r.get("mode");try(var c=db()){c.setAutoCommit(false);try(var p=c.prepareStatement(mode.equals("gap")?"UPDATE authority.completions SET sequence=101 WHERE tenant_id=? AND sequence=1":"UPDATE authority.completions SET payload=? WHERE tenant_id=? AND sequence=(SELECT max(sequence) FROM authority.completions WHERE tenant_id=?)")){if(mode.equals("gap")){p.setString(1,tenant);}else{var current=state(tenant);var ledger=unpack(current.get("ledger"));var op=unpack(ledger.get(""+ledger.size()));if(mode.equals("missing"))op.put("value","");else op.put("state","UNKNOWN");p.setString(1,packed(op));p.setString(2,tenant);p.setString(3,tenant);}require(p.executeUpdate()==1,"FIXTURE_RECORD_NOT_FOUND");}try(var p=c.prepareStatement("UPDATE authority.current_state SET version=version+1 WHERE tenant_id=?")){p.setString(1,tenant);p.executeUpdate();}c.commit();}return map("code","OK");}
            case "fixture-reset-ledger":{String tenant=r.get("tenant");var entries=unpack(r.get("ledger"));try(var c=db()){c.setAutoCommit(false);for(String body:entries.values()){var op=unpack(body);require(op.get("tenant").equals(tenant)&&op.get("state").equals("COMMITTED"),"FIXTURE_LEDGER_SCOPE");try(var p=c.prepareStatement("UPDATE authority.completions SET semantic_digest=?,sequence=?,payload=?,outcome='COMMITTED' WHERE tenant_id=? AND operation_id=?")){p.setString(1,op.get("digest"));p.setLong(2,Long.parseLong(op.get("sequence")));p.setString(3,body);p.setString(4,tenant);p.setString(5,op.get("id"));require(p.executeUpdate()==1,"FIXTURE_RECORD_NOT_FOUND");}}try(var p=c.prepareStatement("UPDATE authority.current_state SET version=version+1 WHERE tenant_id=?")){p.setString(1,tenant);p.executeUpdate();}c.commit();}return map("code","OK");}
            default:break;
        }
        require(available,"AUTHORITY_UNAVAILABLE");
        if(cmd.equals("snapshot")){require(admin||Set.of("source-owner","restored-owner","recovery-executor").contains(peer),"SNAPSHOT_PEER");var s=state(r.get("tenant"));if(fault.equals("rollback"))s=new TreeMap<>(Objects.requireNonNull(historical.get(r.get("tenant"))));if(fault.equals("incarnation"))s.put("authority-incarnation","OLD");if(fault.equals("conflict"))s.put("fence","999999");s.put("nonce",r.get(admin?"challenge":"nonce"));return signed(s);}
        if(cmd.equals("consume")){require(peer.equals("recovery-executor"),"RECOVERY_EXECUTOR_REQUIRED");var g=unpack(r.get("body"));verify(d,g,r.get("signature"));require(g.get("attempt").equals(r.get("attempt")),"GRANT_ATTEMPT_MISMATCH");var now=state(g.get("tenant"));for(String f:List.of("tenant","cell","deployment","placement","credential","fence","revision"))require(now.get(f).equals(g.get(f)),"STALE_GRANT");require(System.currentTimeMillis()<Long.parseLong(g.get("expires")),"EXPIRED_GRANT");try(var c=db()){c.setAutoCommit(false);try(var p=c.prepareStatement("SELECT body,state,consumed_by FROM authority.recovery_grants WHERE grant_id=? FOR UPDATE")){p.setString(1,g.get("grant"));try(var result=p.executeQuery()){require(result.next()&&result.getString(1).equals(r.get("body")),"UNKNOWN_OR_MODIFIED_GRANT");require(result.getString(2).equals("ISSUED")||(result.getString(2).equals("CONSUMED")&&g.get("attempt").equals(result.getString(3))),"GRANT_CONSUMED");}}try(var p=c.prepareStatement("UPDATE authority.recovery_grants SET state='CONSUMED',consumed_by=? WHERE grant_id=?")){p.setString(1,g.get("attempt"));p.setString(2,g.get("grant"));p.executeUpdate();}c.commit();}return map("code","OK");}
        if(cmd.equals("acknowledge")){require(peer.equals("recovery-executor"),"RECOVERY_EXECUTOR_REQUIRED");var g=unpack(r.get("body"));verify(d,g,r.get("signature"));var now=state(g.get("tenant"));for(String f:List.of("placement","credential","fence","revision"))require(now.get(f).equals(g.get(f)),"AUTHORITY_CHANGED_DURING_RECOVERY");require(!now.get("suspended").equals("true")&&System.currentTimeMillis()<Long.parseLong(g.get("expires")),"ACTIVATION_GRANT_INVALID");try(var c=db()){c.setAutoCommit(false);try(var p=c.prepareStatement("SELECT body,state,consumed_by FROM authority.recovery_grants WHERE grant_id=? FOR UPDATE")){p.setString(1,g.get("grant"));try(var row=p.executeQuery()){require(row.next()&&row.getString(1).equals(r.get("body"))&&row.getString(2).equals("CONSUMED")&&row.getString(3).equals(g.get("attempt")),"ACTIVATION_GRANT_NOT_CONSUMED_BY_ATTEMPT");}}try(var p=c.prepareStatement("INSERT INTO authority.activations VALUES (?,?,?,?,?,'ACKNOWLEDGED') ON CONFLICT(tenant_id) DO UPDATE SET attempt_id=EXCLUDED.attempt_id,destination_id=EXCLUDED.destination_id,incarnation=EXCLUDED.incarnation,version=EXCLUDED.version,state=EXCLUDED.state")){p.setString(1,g.get("tenant"));p.setString(2,g.get("attempt"));p.setString(3,g.get("destination"));p.setString(4,g.get("incarnation"));p.setLong(5,Long.parseLong(g.get("revision")));p.executeUpdate();}c.commit();}var ack=new TreeMap<>(g);ack.put("data-digest",r.get("data-digest"));ack.put("acknowledged","true");return signed(ack);}
        if(cmd.equals("record")){require(Set.of("source-owner","restored-owner").contains(peer),"COMPLETION_OWNER_REQUIRED");var op=unpack(r.get("body"));try(var c=db()){c.setAutoCommit(false);try(var p=c.prepareStatement("INSERT INTO authority.completions VALUES (?,?,?,?,?,'COMMITTED') ON CONFLICT(tenant_id,operation_id) DO NOTHING")){p.setString(1,op.get("tenant"));p.setString(2,op.get("id"));p.setString(3,op.get("digest"));p.setLong(4,Long.parseLong(op.get("sequence")));p.setString(5,packed(op));p.executeUpdate();}try(var p=c.prepareStatement("UPDATE authority.current_state SET version=version+1 WHERE tenant_id=?")){p.setString(1,op.get("tenant"));p.executeUpdate();}c.commit();}return map("code","OK");}
        throw new Denied("AUTHORITY_COMMAND");
    }
    public static void main(String[] args)throws Exception{var a=new LabRecoveryAuthority(Path.of(args[0]));serve(a.d,args[1],a::handle);}
}
